const input = $input.first().json.body || $input.first().json;
const clientNip = input.client_nip;

if (!clientNip || !/^\d{10}$/.test(clientNip)) {
  throw new Error('Invalid or missing client_nip. Must be exactly 10 digits.');
}

return [{ json: { client_nip: clientNip } }];

const clientData = $('Get Client Config').first().json;
const pubKeyResponse = $input.first().json;

// Find the KsefTokenEncryption certificate
let certBase64 = '';
if (Array.isArray(pubKeyResponse)) {
  const encCert = pubKeyResponse.find(c => {
    const usages = c.usage || [];
    return usages.some(u => (u.usage || []).includes('KsefTokenEncryption'));
  }) || pubKeyResponse[0];
  certBase64 = encCert.certificate || encCert.publicKey || '';
} else if (pubKeyResponse.certificate) {
  certBase64 = pubKeyResponse.certificate;
} else if (pubKeyResponse.publicKey) {
  certBase64 = pubKeyResponse.publicKey;
}

const certPem = '-----BEGIN CERTIFICATE-----\n' + certBase64.match(/.{1,64}/g).join('\n') + '\n-----END CERTIFICATE-----';

return [{
  json: {
    client_nip: clientData.nip,
    ksef_token: clientData.ksef_token_encrypted,
    cert_pem: certPem
  }
}];

const crypto = require('crypto');

const challengeResponse = $input.first().json;
const authData = $('Prepare Auth Data').first().json;

const challenge = challengeResponse.challenge;
const timestamp = challengeResponse.timestamp;
const token = authData.ksef_token;
const certPem = authData.cert_pem;

if (!token) {
  throw new Error('No KSeF token found for client. Configure ksef_token_encrypted in clients table.');
}

// Extract public key from X.509 certificate
const publicKey = crypto.createPublicKey(certPem);

// Encrypt: token|timestampMs with RSA-OAEP SHA-256
const timestampMs = new Date(timestamp).getTime();
const plaintext = `${token}|${timestampMs}`;

const encrypted = crypto.publicEncrypt({
  key: publicKey,
  padding: crypto.constants.RSA_PKCS1_OAEP_PADDING,
  oaepHash: 'sha256',
}, Buffer.from(plaintext, 'utf-8'));

return [{
  json: {
    challenge: challenge,
    timestamp: timestamp,
    encrypted_token: encrypted.toString('base64'),
    client_nip: authData.client_nip
  }
}];

const response = $input.first().json;

// v2 returns authenticationToken directly
const authToken = response.authenticationToken?.token || response.authenticationToken;
const referenceNumber = response.referenceNumber;

if (!authToken) {
  throw new Error('No authenticationToken in response: ' + JSON.stringify(response));
}

return [{
  json: {
    authenticationToken: authToken,
    referenceNumber: referenceNumber,
    client_nip: $('Encrypt Token RSA-OAEP').first().json.client_nip
  }
}];

const redeemResponse = $input.first().json;
const authData = $('Extract Auth Token').first().json;

const accessToken = redeemResponse.accessToken?.token || redeemResponse.accessToken;
const refreshToken = redeemResponse.refreshToken?.token || redeemResponse.refreshToken;

if (!accessToken) {
  throw new Error('No accessToken in redeem response: ' + JSON.stringify(redeemResponse));
}

return [{
  json: {
    success: true,
    accessToken: accessToken,
    refreshToken: refreshToken,
    referenceNumber: authData.referenceNumber,
    client_nip: authData.client_nip
  }
}];

const error = $input.first().json;
return [{
  json: {
    error_type: 'ksef_auth_error',
    message: error.message || error.execution?.error?.message || 'Unknown auth error',
    workflow: 'KSeF - Authenticate v2',
    timestamp: new Date().toISOString()
  }
}];

